using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace Stackshot
{
    static class InPlaceCaptureTests
    {
        static Bitmap Source(int width,int height){var image=new Bitmap(width,height);using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(233,239,246));using(var p=new Pen(Color.FromArgb(191,204,219)))for(int x=20;x<width;x+=40)g.DrawLine(p,x,30,x,height-30);using(var b=new SolidBrush(Color.White))g.FillRectangle(b,100,75,width-180,height-160);using(var p=new Pen(Color.FromArgb(76,99,122),3)){g.DrawRectangle(p,200,180,320,220);g.DrawLine(p,360,180,360,400);g.DrawRectangle(p,600,210,190,170);}using(var font=new Font("Microsoft YaHei UI",15))g.DrawString("Synthetic architecture fixture · 合成图纸",font,Brushes.SlateGray,125,92);}return image;}
        static CaptureOverlay Overlay(){return new CaptureOverlay(Source(1280,800),new Rectangle(-1280,0,1280,800),new Rectangle(-1100,130,850,430),new[]{new Rectangle(-1280,0,1280,760)});}
        static System.Collections.Generic.IEnumerable<Control> Children(Control root){foreach(Control c in root.Controls){yield return c;foreach(var d in Children(c))yield return d;}}
        static void Click(Button b){typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(b,new object[]{EventArgs.Empty});}
        static string Hash(Bitmap image){using(var stream=new MemoryStream()){image.Save(stream,System.Drawing.Imaging.ImageFormat.Png);using(var hash=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(hash.ComputeHash(stream.ToArray()));}}
        static void ShapeInside(Canvas canvas){var shape=ScreenCraftTests.Mark(Tool.Rect,260,210,500,350);shape.CornerRadius=16;shape.Dash=DashStyle.Dash;shape.FillEnabled=true;shape.FillColor=Color.FromArgb(55,255,70,100);canvas.AddAnnotation(shape);}
        public static void Run(Action<string,Action> run,Action<bool,string> check,string output)
        {
            run("in-place/negative desktop origin maps selection without scaling",delegate{check(CaptureOverlayGeometry.LocalSelection(new Rectangle(-1100,130,850,430),new Rectangle(-1280,0,1280,800))==new Rectangle(180,130,850,430),"negative desktop origin");using(var overlay=Overlay()){var c=overlay.AnnotationCanvas;check(c.ImageToControl(new PointF(260,210))==new Point(260,210),"canvas rescaled screenshot");check(c.ZoomPercent==100&&c.Bounds==new Rectangle(0,0,1280,800)&&overlay.FormBorderStyle==FormBorderStyle.None&&!overlay.Visible,"not in-place or shown");}});
            run("in-place/surround dims only outside and preserves source pixels",delegate{using(var source=new Bitmap(600,400))using(var painted=new Bitmap(600,400)){using(var g=Graphics.FromImage(source))g.Clear(Color.FromArgb(200,160,120));using(var g=Graphics.FromImage(painted))CaptureOverlayGeometry.PaintSurround(g,source,new Rectangle(100,80,300,200));check(painted.GetPixel(120,100).ToArgb()==source.GetPixel(120,100).ToArgb(),"selection dimmed");check(painted.GetPixel(20,20).R<150&&source.GetPixel(20,20).R==200,"outside not dimmed or source modified");}});
            run("in-place/toolbar remains inside selected monitor at every corner",delegate{var area=new Rectangle(0,0,1280,760);foreach(var selected in new[]{new Rectangle(0,0,200,100),new Rectangle(1080,660,200,100),new Rectangle(0,660,200,100),new Rectangle(1080,0,200,100),area}){var toolbar=CaptureOverlayGeometry.PlaceToolbar(selected,new Size(728,102),area);check(area.Contains(toolbar),"toolbar offscreen "+toolbar);}});
            run("in-place/rapid range preview keeps native bars stationary and commits the release in one undo step",delegate{
                using(var overlay=Overlay()){
                    var c=overlay.AnnotationCanvas;
                    var start=Rectangle.Round(c.Crop);
                    var bars=Children(overlay).OfType<CaptureBar>().ToArray();
                    var materials=bars.Select(b=>b.Material).ToArray();
                    var locations=bars.Select(b=>b.Bounds).ToArray();
                    overlay.BeginRangeDrag(4,new Point(start.Right,start.Bottom));
                    for(int i=1;i<=120;i++)overlay.UpdateRangeDrag(new Point(start.Right-i,start.Bottom-i));
                    for(int i=0;i<bars.Length;i++)
                        check(ReferenceEquals(materials[i],bars[i].Material)&&bars[i].Bounds==locations[i],"bar moved or recomputed blur during gesture");
                    check(!c.CanUndo,"intermediate position entered undo history");
                    c.CaptureUp(new MouseEventArgs(MouseButtons.Left,1,start.Right-25,start.Bottom+10,0));
                    check(c.Crop.Right==start.Right-25&&c.Crop.Bottom==start.Bottom+10,"final input lost");
                    c.Undo();
                    check(c.Crop==start&&!c.CanUndo&&c.CanRedo,"gesture must be exactly one undo step");
                    overlay.BeginRangeDrag(8,start.Location);
                    overlay.UpdateRangeDrag(new Point(start.X+25,start.Y+15));
                    typeof(Control).GetMethod("OnMouseCaptureChanged",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{EventArgs.Empty});
                    check(c.Crop==start&&!c.CanUndo&&c.CanRedo,"lost capture did not roll back without disturbing redo");
                }
            });
            run("in-place/chrome follows display scale while the crop and export use physical pixels",delegate{
                using(var overlay=Overlay()){
                    var c=overlay.AnnotationCanvas;
                    var crop=c.Crop;
                    var rect=Children(overlay).OfType<CaptureIconButton>().Single(b=>b.AccessibleName=="矩形 R");
                    foreach(float scale in new[]{1f,1.25f,1.5f,2f,1f}){
                        overlay.SetChromeScale(scale);c.SetTool(Tool.Rect);
                        check(rect.Width==(int)Math.Round(34*scale)&&c.Crop==crop,"scaled image or accumulated rounding");
                        check(c.ClientRectangle.Contains(overlay.ToolbarBounds)&&c.ClientRectangle.Contains(overlay.OptionsBounds),"controls left viewport");
                        using(var result=c.Render())check(result.Size==Size.Round(crop.Size),"DPI changed exported dimensions");
                    }
                }
            });
            run("in-place/eight handles and movement clamp to frozen desktop",delegate{var original=new Rectangle(100,80,300,200);var bounds=new Rectangle(0,0,600,400);check(CaptureOverlayGeometry.Handles(original).Length==8,"handles");for(int i=0;i<8;i++){var next=CaptureOverlayGeometry.DragSelection(original,i,new Point(1000,-1000),bounds);check(bounds.Contains(next)&&next.Width>=1&&next.Height>=1,"invalid resize");}check(CaptureOverlayGeometry.DragSelection(original,8,new Point(-999,-999),bounds)==new Rectangle(0,0,300,200),"move bounds");});
            run("in-place/range drag commits one undo step and cancel restores range",delegate{using(var overlay=Overlay()){var before=overlay.AnnotationCanvas.Crop;overlay.BeginRangeDrag(4,new Point(1030,560));overlay.UpdateRangeDrag(new Point(1060,590));overlay.UpdateRangeDrag(new Point(1100,620));overlay.EndRangeDrag();check(overlay.AnnotationCanvas.Crop.Width==920,"resize not applied");overlay.AnnotationCanvas.Undo();check(overlay.AnnotationCanvas.Crop==before&&overlay.AnnotationCanvas.Bounds==new Rectangle(0,0,1280,800),"range undo or canvas position");overlay.BeginRangeDrag(8,new Point(180,130));overlay.UpdateRangeDrag(new Point(220,160));overlay.CancelRangeDrag();check(overlay.AnnotationCanvas.Crop==before,"cancel range");}});
            run("in-place/export project trims uncaptured desktop and shifts annotation coordinates",delegate{using(var overlay=Overlay()){ShapeInside(overlay.AnnotationCanvas);using(var doc=overlay.AnnotationCanvas.ExportDocument()){check(doc.Source.Size==new Size(850,430)&&doc.Crop==new Rectangle(0,0,850,430),"full desktop leaked into project");check(doc.Shapes[0].A==new PointF(80,80)&&doc.Shapes[0].CornerRadius==16&&doc.Shapes[0].FillColor.A==55,"annotation shift or attributes");using(var actual=overlay.AnnotationCanvas.Render())using(var saved=doc.Render())check(Hash(actual)==Hash(saved),"export altered pixels");string file=Path.Combine(output,"in-place-project.sccraft");doc.Save(file);using(var reopened=AnnotationDocument.Open(file))check(reopened.Source.Size==doc.Source.Size&&reopened.Shapes[0].Id==doc.Shapes[0].Id,"project reload");}}});
            run("in-place/mosaic survives cropped export with identical pixels at selection edges",delegate{var image=new Bitmap(1024,600);for(int y=0;y<600;y++)for(int x=0;x<1024;x++)image.SetPixel(x,y,((x/3+y/4)%2)==0?Color.Black:Color.White);using(var overlay=new CaptureOverlay(image,new Rectangle(0,0,1024,600),new Rectangle(280,100,600,400),new[]{new Rectangle(0,0,1024,600)})){overlay.AnnotationCanvas.AddAnnotation(ScreenCraftTests.Mark(Tool.Pixelate,240,150,400,300));using(var doc=overlay.AnnotationCanvas.ExportDocument())using(var a=overlay.AnnotationCanvas.Render())using(var b=doc.Render()){check(doc.Shapes[0].MosaicBlock==13,"legacy mosaic strength lost");check(Hash(a)==Hash(b),"cropping changed mosaic pixels");}}});
            run("in-place/rich toolbar updates same annotation engine and retains inspector",delegate{using(var overlay=Overlay()){var all=Children(overlay).ToArray();foreach(string label in new[]{"矩形 R","点标注 Q","云线标注","数字点标注","马赛克 M","完成并复制 Enter","详细标注属性"})check(all.Any(c=>c.AccessibleName==label),"missing control "+label);Click((Button)all.Single(c=>c.AccessibleName=="圆角矩形"));Click((Button)all.Single(c=>c.AccessibleName=="半透明填充"));Click((Button)all.Single(c=>c.AccessibleName=="虚线（其他线型见详细属性）"));check(overlay.AnnotationCanvas.DefaultStyle.Radius==12&&overlay.AnnotationCanvas.DefaultStyle.FillEnabled&&overlay.AnnotationCanvas.DefaultStyle.Dash==DashStyle.Dash,"toolbar disconnected");check(!all.OfType<AnnotationInspector>().Any(),"inspector eagerly constructed");Click((Button)all.Single(c=>c.AccessibleName=="详细标注属性"));check(Children(overlay).OfType<AnnotationInspector>().Count()==1&&!overlay.Visible,"rich inspector absent or GUI shown");}});
            run("in-place/copy uses production rendered crop with no clipboard access",delegate{Bitmap copied=null;using(var overlay=Overlay()){ShapeInside(overlay.AnnotationCanvas);overlay.CopyOutput=delegate(Bitmap image){copied=new Bitmap(image);};Click(Children(overlay).OfType<Button>().Single(c=>c.AccessibleName=="完成并复制 Enter"));}using(copied)check(copied!=null&&copied.Size==new Size(850,430),"copy output dimensions");});
            run("in-place/failed copy and export commands keep editable capture available",delegate{using(var overlay=Overlay()){ShapeInside(overlay.AnnotationCanvas);string error=null;overlay.CommandError=delegate(string message){error=message;};overlay.CopyOutput=delegate{throw new System.Runtime.InteropServices.ExternalException("fixture clipboard busy");};Click(Children(overlay).OfType<Button>().Single(c=>c.AccessibleName=="完成并复制 Enter"));check(error.Contains("fixture clipboard busy")&&!overlay.IsDisposed&&overlay.AnnotationCanvas.AnnotationCount==1,"failed copy discarded edits");overlay.ExecuteCommand(delegate{throw new IOException("fixture folder denied");});check(error.Contains("fixture folder denied")&&!overlay.IsDisposed,"failed menu command discarded editor");}});
            run("in-place/pin handoff remains editable and owns only selected source",delegate{AnnotationDocument saved=null;using(var overlay=Overlay()){ShapeInside(overlay.AnnotationCanvas);overlay.PinOutput=delegate(AnnotationDocument doc){saved=doc;};Click(Children(overlay).OfType<Button>().Single(c=>(c.AccessibleName??"").StartsWith("钉在屏幕")));}using(saved)using(var pin=PinWindow.CreateHidden(saved.Clone(),new Rectangle(0,0,1920,1080)))using(var edit=pin.ExportDocument()){check(saved.Shapes.Length==1&&edit.Source.Size==new Size(850,430)&&edit.Shapes[0].CornerRadius==16&&!pin.Visible,"editable pin handoff flattened or shown");}});
            run("in-place/production visual preview uses synthetic fixture only",delegate{using(var overlay=Overlay()){ShapeInside(overlay.AnnotationCanvas);overlay.AnnotationCanvas.SetTool(Tool.Arrow);using(var preview=overlay.RenderSyntheticPreview())preview.Save(Path.Combine(output,"in-place-overlay-synthetic.png"));check(overlay.ClientRectangle.Contains(overlay.ToolbarBounds)&&overlay.ClientRectangle.Contains(overlay.OptionsBounds)&&overlay.OptionsBounds.Width<=overlay.ToolbarBounds.Width&&!overlay.Visible,"layout or desktop boundary");}});
            run("in-place/narrow monitor wraps real toolbar controls inside available bounds",delegate{using(var overlay=new CaptureOverlay(new Bitmap(400,700),new Rectangle(0,0,400,700),new Rectangle(20,20,300,400),new[]{new Rectangle(0,0,400,660)})){check(new Rectangle(0,0,400,660).Contains(overlay.ToolbarBounds)&&new Rectangle(0,0,400,660).Contains(overlay.OptionsBounds),"toolbar outside narrow display");foreach(var flow in Children(overlay).OfType<FlowLayoutPanel>().Where(p=>p.Controls.OfType<CaptureIconButton>().Any()))foreach(Control child in flow.Controls)if(overlay.IsOptionShown(child))check(child.Bottom<=flow.Height,"toolbar row clipped");}});
            run("capture style/slider clamps and changes values without mouse injection",delegate{using(var slider=new CaptureSlider()){int changed=0;slider.ValueChanged+=delegate{changed++;};slider.SetAt(-100);check(slider.Value==slider.Minimum,"minimum");slider.SetAt(10000);check(slider.Value==slider.Maximum&&changed==2,"maximum");}});
            run("capture style/slider keyboard and wheel handlers adjust actual values",delegate{using(var slider=new CaptureSlider()){slider.Value=8;typeof(CaptureSlider).GetMethod("OnKeyDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(slider,new object[]{new KeyEventArgs(Keys.Right)});check(slider.Value==9,"keyboard adjustment");typeof(CaptureSlider).GetMethod("OnMouseWheel",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(slider,new object[]{new MouseEventArgs(MouseButtons.None,0,0,0,-120)});check(slider.Value==8,"wheel adjustment");}});
            run("in-place/color sample updates stroke and copies formatted value through adapter",delegate{using(var overlay=Overlay()){string copied=null;overlay.CopyColorText=delegate(string value){copied=value;};overlay.ApplySampledColor(Color.FromArgb(12,171,239));check(copied=="rgb(12, 171, 239)"&&overlay.AnnotationCanvas.ActiveColor.ToArgb()==Color.FromArgb(12,171,239).ToArgb(),"sample copy or stroke");overlay.CopyColorText=delegate{throw new System.Runtime.InteropServices.ExternalException("fixture clipboard busy");};overlay.ApplySampledColor(Color.Red);check(!overlay.IsDisposed,"clipboard busy ended editor");var note=ScreenCraftTests.Mark(Tool.Counter,300,300,300,300);note.Text="note";overlay.AnnotationCanvas.AddAnnotation(note);var anchorInk=overlay.AnnotationCanvas.ActiveColor;overlay.ApplySampledColor(Color.Yellow);check(overlay.AnnotationCanvas.ActiveTextColor.ToArgb()==Color.White.ToArgb()&&overlay.AnnotationCanvas.ActiveColor.ToArgb()==Color.Yellow.ToArgb(),"sampled color did not update label background and point together");}});
            run("pins/wheel and keys scale uniformly and leave source pixels untouched",delegate{using(var pin=PinWindow.CreateHidden(AnnotationDocument.FromImage(new Bitmap(637,349)),new Rectangle(0,0,1920,1080))){var before=pin.DisplayedImageSize;pin.ApplyPinWheel(120,new Point(100,70),Keys.None);check(Math.Abs(pin.DisplayedImageSize.Width-637*pin.State.Zoom)<=.51&&Math.Abs(pin.DisplayedImageSize.Height-349*pin.State.Zoom)<=.51,"aspect distortion");float zoom=pin.State.Zoom;pin.ApplyPinWheel(120,new Point(100,70),Keys.Control);check(pin.State.Zoom==zoom&&pin.State.OpacityPercent==100,"Ctrl wheel zoomed");pin.ApplyPinWheel(-120,new Point(100,70),Keys.Control);check(pin.State.OpacityPercent==95&&pin.State.Zoom==zoom,"opacity semantics");pin.ApplyPinWheel(0,Point.Empty,Keys.None);check(pin.State.Zoom==zoom,"zero wheel changed scale");check(pin.ApplyPinKey(Keys.Control|Keys.Oemplus),"plus key ignored");pin.ApplyPinKey(Keys.Control|Keys.D0);check(pin.DisplayedImageSize==new Size(637,349),"actual size");using(var doc=pin.ExportDocument())check(doc.Source.Size==new Size(637,349),"zoom mutated source");check(!pin.Visible,"visible pin");}});
            run("pins/corner drag changes uniform scale and Escape can restore scale",delegate{using(var pin=PinWindow.CreateHidden(AnnotationDocument.FromImage(new Bitmap(600,300)),new Rectangle(-1920,0,1920,1080))){var body=pin.DisplayedImageSize;var origin=pin.Bounds.Location;pin.BeginProportionalResize(new Point(600,300));pin.UpdateProportionalResize(new Point(720,360));check(Math.Abs(pin.State.Zoom-1.2)<.001&&pin.DisplayedImageSize==new Size(720,360)&&pin.Bounds.Location==origin,"corner resize distorted or moved origin");pin.CancelProportionalResize();check(pin.DisplayedImageSize==body,"resize cancel");pin.BeginProportionalResize(new Point(600,300));pin.UpdateProportionalResize(new Point(480,240));pin.EndProportionalResize();check(pin.DisplayedImageSize==new Size(480,240)&&!pin.Visible,"shrink failed");}});
            run("pins/scaling A leaves independent B unchanged and clamps extreme scale",delegate{using(var a=PinWindow.CreateHidden(AnnotationDocument.FromImage(new Bitmap(300,200)),new Rectangle(0,0,1920,1080)))using(var b=PinWindow.CreateHidden(AnnotationDocument.FromImage(new Bitmap(300,200)),new Rectangle(0,0,1920,1080))){a.ApplyPinWheel(240,Point.Empty,Keys.None);check(Math.Abs(a.State.Zoom-1.21)<.001&&b.State.Zoom==1,"scale shared");a.ZoomAt(.0001f,Point.Empty);check(a.DisplayedImageSize.Width>=40&&a.DisplayedImageSize.Height>=26,"minimum unusable");a.ZoomAt(100,Point.Empty);check(a.State.Zoom<=4&&b.DisplayedImageSize==new Size(300,200),"maximum or isolation");}});
            run("pins/S toggles thumbnail and Z restores previous scale",delegate{using(var pin=PinWindow.CreateHidden(AnnotationDocument.FromImage(new Bitmap(600,300)),new Rectangle(0,0,1920,1080))){pin.ZoomAt(.7f,Point.Empty);pin.ApplyPinKey(Keys.Z);check(pin.State.Zoom==1,"Z actual");pin.ApplyPinKey(Keys.Z);check(Math.Abs(pin.State.Zoom-.7)<.001,"Z restore");pin.ApplyPinKey(Keys.S);check(pin.State.Thumbnail,"S thumbnail");pin.ApplyPinKey(Keys.S);check(!pin.State.Thumbnail&&Math.Abs(pin.State.Zoom-.7)<.001,"S restore");}});
        }
    }
}
